<?php
declare(strict_types=1);
$config=__DIR__.'/config.php';
if(is_file($config)){http_response_code(404);exit('Already installed. Delete install.php from your hosting account.');}
$error='';
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $host=trim($_POST['host']??'localhost');$name=trim($_POST['dbname']??'');$user=trim($_POST['dbuser']??'');$pass=$_POST['dbpass']??'';$admin=trim($_POST['admin']??'');$email=strtolower(trim($_POST['email']??''));$apass=$_POST['apass']??'';
 if(!$name||!$user||!$admin||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($apass)<12){$error='Complete all fields. Administrator password must be at least 12 characters.';}
 else try{
  $pdo=new PDO("mysql:host=$host;dbname=$name;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
  $sql=[
  "CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
  "CREATE TABLE courses(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,code VARCHAR(30) NOT NULL,name VARCHAR(150) NOT NULL,credits TINYINT UNSIGNED NOT NULL DEFAULT 3,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
  "CREATE TABLE tasks(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,course VARCHAR(100) DEFAULT '',due_date DATE NULL,status VARCHAR(10) NOT NULL DEFAULT 'todo',priority VARCHAR(10) NOT NULL DEFAULT 'normal',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
  "CREATE TABLE grades(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,course_id INT UNSIGNED NOT NULL,assessment VARCHAR(150) NOT NULL,score DECIMAL(5,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
  "CREATE TABLE events(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,event_date DATE NOT NULL,start_time TIME NULL,location VARCHAR(150) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,event_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"];
  foreach($sql as $q)$pdo->exec($q);
  $q=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$q->execute([$admin,$email,password_hash($apass,PASSWORD_DEFAULT)]);
  $data=['db_host'=>$host,'db_name'=>$name,'db_user'=>$user,'db_pass'=>$pass];
  if(file_put_contents($config,"<?php\nreturn ".var_export($data,true).";\n",LOCK_EX)===false)throw new RuntimeException('Cannot write config.php. Check directory permissions.');
  @chmod($config,0600);header('Location: ./');exit;
 }catch(Throwable $ex){$error='Setup failed: '.e($ex->getMessage());}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install StudentLife</title><style>body{margin:0;background:#f4f6fb;color:#17243a;font:15px system-ui;display:grid;place-items:center;min-height:100vh;padding:20px;box-sizing:border-box}.box{background:white;border:1px solid #e4eaf2;border-radius:16px;padding:30px;width:min(540px,100%);box-sizing:border-box}h1{margin:5px 0}.muted{color:#718096;font-size:13px}.field{display:grid;gap:6px;margin:12px 0}.field label{font-size:12px;font-weight:650;color:#53627a}.field input{padding:11px;border:1px solid #dce3ed;border-radius:8px;font:inherit}.btn{border:0;background:#315efb;color:white;padding:12px 16px;border-radius:9px;font-weight:700;width:100%;cursor:pointer}.error{background:#fff0f0;color:#a33;padding:12px;border-radius:8px;font-size:13px}</style></head><body><div class="box"><div style="color:#315efb;font-weight:800;letter-spacing:1px">STUDENTLIFE · INSTALLER</div><h1>Set up your workspace</h1><p class="muted">Enter your cPanel MySQL details and create the first account. Database credentials are saved in a private PHP config file on your hosting account.</p><?php if($error):?><p class="error"><?=$error?></p><?php endif;?><form method="post"><h3>Database connection</h3><div class="field"><label>Database host (usually localhost)</label><input name="host" value="<?=e($_POST['host']??'localhost')?>" required></div><div class="field"><label>Full database name (include cPanel prefix)</label><input name="dbname" value="<?=e($_POST['dbname']??'')?>" required></div><div class="field"><label>Full database username (include cPanel prefix)</label><input name="dbuser" value="<?=e($_POST['dbuser']??'')?>" required></div><div class="field"><label>Database password</label><input type="password" name="dbpass" required></div><h3>Administrator account</h3><div class="field"><label>Your name</label><input name="admin" value="<?=e($_POST['admin']??'')?>" required></div><div class="field"><label>Email address</label><input type="email" name="email" value="<?=e($_POST['email']??'')?>" required></div><div class="field"><label>Password (12+ characters)</label><input type="password" name="apass" minlength="12" required></div><button class="btn">Install StudentLife</button></form><p class="muted">After installation, delete install.php from cPanel File Manager. Keep config.php; web access to it is blocked.</p></div></body></html>